parameters.jsCode:
const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || `req_${executionId}`;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
function parseEmbeddedJson(value) {
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  if (!candidate.startsWith('{') || !candidate.endsWith('}')) return null;
  try { return JSON.parse(candidate); } catch { return null; }
}
const embedded = parseEmbeddedJson(aiText) || {};
const explicit = input.context?.route_decision || embedded.output?.route_decision || embedded.route_decision || null;
const decision = explicit?.decision || 'answer_direct';
const targetAgent = explicit?.target_agent || (['retrieve_knowledge','ingest_or_stage_knowledge'].includes(decision) ? 'knowledge_fabric_agent' : ['activate_skill','create_skill'].includes(decision) ? 'agentic_butler' : decision === 'request_human_clarification' ? 'human' : 'actor_twin');
const routeDecision = {
  decision,
  target_agent: targetAgent,
  intent: explicit?.intent || input.intent || (decision === 'activate_skill' ? 'activate_skill' : decision === 'create_skill' ? 'create_skill' : decision === 'ingest_or_stage_knowledge' ? 'ingest_concept' : decision === 'retrieve_knowledge' ? 'retrieve_context' : 'answer_question'),
  visible_state: explicit?.visible_state || (decision === 'answer_direct' ? 'answering' : targetAgent === 'knowledge_fabric_agent' ? 'using_knowledge' : targetAgent === 'agentic_butler' ? 'activating_skill' : 'approval_required'),
  approval_required: Boolean(explicit?.approval_required || decision === 'create_skill' || decision === 'request_human_clarification'),
  handoff_required: Boolean(targetAgent !== 'actor_twin' && targetAgent !== 'human'),
  reason: explicit?.reason || 'Actor Twin route decision normalized for direct n8n orchestration.'
};
const delegateEnvelope = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: `${requestId}_${routeDecision.target_agent}`,
  timestamp: new Date().toISOString(),
  agent_id: routeDecision.target_agent,
  intent: routeDecision.intent,
  principal: input.principal || { twin_id: input.twin_id || 'florian', display_name: input.display_name || 'Florian' },
  input: input.input || { query: input.chatInput || input.message || '' },
  context: { ...(input.context || {}), called_by: 'actor_twin', route_decision: routeDecision, orchestration_model: 'uat_n8n_direct' },
  approval: input.approval || { required: false, reason: 'Delegated by Actor Twin route decision.' }
};
return [{ json: { input, ai_text: aiText, request_id: requestId, route_decision: routeDecision, delegate_envelope: delegateEnvelope, actor_answer_candidate: embedded.output?.answer || embedded.answer || aiText } }];

const current = $json;
const normalized = current.route_decision ? current : $('Normalize route decision').first().json;
const delegate = current.agent_id && current.agent_id !== 'actor_twin' ? current : null;
const route = normalized.route_decision;
const approvalRequired = Boolean(route.approval_required || delegate?.status === 'approval_required');
return [{ json: {
  envelope_version: normalized.input?.envelope_version || '0.1.0',
  request_id: normalized.request_id,
  agent_id: 'actor_twin',
  status: approvalRequired ? 'approval_required' : 'completed',
  output: {
    answer: delegate?.output?.answer || delegate?.output?.summary || normalized.actor_answer_candidate || 'Actor Twin completed orchestration.',
    route_decision: route,
    delegate_result: delegate,
    confidence: delegate?.output?.confidence || 0.78,
    citations: delegate?.output?.citations || [],
    actor_review: 'Actor Twin delegated execution, then shaped the final response boundary.'
  },
  approval: delegate?.approval || (approvalRequired ? { required: true, gate: route.intent, summary: route.reason, proposed_action: 'Human review required before continuing.' } : { required: false }),
  trace: {
    stored: true,
    trace_id: `n8n_actor_orchestration_${Date.now()}`,
    orchestration_model: 'uat_n8n_direct',
    used_agents: ['actor_twin'].concat(route.target_agent && !['actor_twin','human'].includes(route.target_agent) ? [route.target_agent] : []),
    route_decision: route.decision,
    target_agent: route.target_agent,
    delegate_trace_id: delegate?.trace?.trace_id || ''
  }
} }];
